<?php
require __DIR__.'/includes/bootstrap.php';
$token=$_GET['token']??''; $ok=false; $a=null;
if($token){$st=db()->prepare('SELECT a.*,c.name client_name,s.name service_name FROM appointments a JOIN clients c ON c.id=a.client_id JOIN services s ON s.id=a.service_id WHERE confirmation_token=?');$st->execute([$token]);$a=$st->fetch();if($a&&$a['status']==='pendente'){db()->prepare("UPDATE appointments SET status='confirmado',confirmed_at=NOW() WHERE id=?")->execute([$a['id']]);$a['status']='confirmado';$ok=true;}elseif($a&&$a['status']==='confirmado')$ok=true;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Confirmação | PG Estética</title><link rel="stylesheet" href="assets/css/style.css"></head><body><section><div class="container narrow"><div class="form-card center"><img class="confirm-logo" src="assets/img/logo.jpeg" alt="PG Estética"><h1><?= $ok?'Agendamento confirmado!':'Link inválido ou indisponível' ?></h1><?php if($ok): ?><p><?= e($a['client_name']) ?>, seu atendimento de <strong><?= e($a['service_name']) ?></strong> está confirmado para <?= date('d/m/Y',strtotime($a['appointment_date'])) ?> às <?= substr($a['appointment_time'],0,5) ?>.</p><?php endif; ?><a class="btn btn-primary" href="index.php">Voltar ao site</a></div></div></section></body></html>
